```sql
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create or replace function public.is_team_member(p_team_id bigint, p_role text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = p_role
  );
$$;

create or replace function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.is_team_member(p_team_id, 'editor');
$$;

create or replace function public.can_delete_document(p_document_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.documents d
    where d.id = p_document_id
      and d.created_by = auth.uid()
  );
$$;

create or replace function public.enforce_team_members_insert()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.user_id is null then
    raise exception 'user_id is required';
  end if;

  if new.role not in ('viewer', 'editor') then
    raise exception 'role must be viewer or editor';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_documents_insert()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.team_id is null then
    raise exception 'team_id is required';
  end if;

  if new.title is null then
    raise exception 'title is required';
  end if;

  if new.created_by is distinct from auth.uid() then
    raise exception 'created_by must be the current user';
  end if;

  if new.deleted_at is not null then
    raise exception 'deleted_at must be null on insert';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_documents_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.team_id is distinct from old.team_id then
    raise exception 'team_id cannot be changed';
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'created_by cannot be changed';
  end if;

  if new.deleted_at is not null and old.deleted_at is null then
    raise exception 'deleted_at can only be set on delete';
  end if;

  if not public.is_team_editor(new.team_id) then
    raise exception 'only editors can edit documents in this team';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_documents_delete()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return old;
  end if;

  if old.created_by is distinct from auth.uid() then
    raise exception 'only the creator can delete a document';
  end if;

  return old;
end;
$$;

create trigger team_members_enforce_insert
before insert on public.team_members
for each row execute function public.enforce_team_members_insert();

create trigger documents_enforce_insert
before insert on public.documents
for each row execute function public.enforce_documents_insert();

create trigger documents_enforce_update
before update on public.documents
for each row execute function public.enforce_documents_update();

create trigger documents_enforce_delete
before delete on public.documents
for each row execute function public.enforce_documents_delete();

create policy teams_select_member
on public.teams
for select
to authenticated
using (public.is_team_member(id, any));

create policy team_members_select_own
on public.team_members
for select
to authenticated
using (user_id = auth.uid());

create policy documents_select_member
on public.documents
for select
to authenticated
using (public.is_team_member(team_id, 'viewer') and deleted_at is null);

create policy documents_insert_editor
on public.documents
for insert
to authenticated
with check (public.is_team_editor(team_id));

create policy documents_update_editor
on public.documents
for update
to authenticated
using (public.is_team_editor(team_id))
with check (public.is_team_editor(team_id));

create policy documents_delete_creator
on public.documents
for delete
to authenticated
using (public.can_delete_document(id));

revoke all on public.teams from anon, authenticated;
revoke all on public.team_members from anon, authenticated;
revoke all on public.documents from anon, authenticated;

grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;

grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;

revoke all on sequence public.documents_id_seq from anon, authenticated;
grant usage, select on sequence public.documents_id_seq to authenticated;
grant all on sequence public.documents_id_seq to service_role;

revoke all on function public.is_team_member(bigint, text) from public, anon;
revoke all on function public.is_team_editor(bigint) from public, anon;
revoke all on function public.can_delete_document(bigint) from public, anon;

grant execute on function public.is_team_member(bigint, text) to authenticated, service_role;
grant execute on function public.is_team_editor(bigint) to authenticated, service_role;
grant execute on function public.can_delete_document(bigint) to authenticated, service_role;
