```sql
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create or replace function public.is_suspended(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select a.suspended from public.accounts a where a.user_id = p_user_id),
    false
  );
$$;

create or replace function public.can_access_file(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.files f
    join public.file_shares s on s.file_id = f.id
    where f.id = p_file_id
      and s.shared_with = p_user_id
      and (s.expires_at is null or s.expires_at > now())
  );
$$;

create or replace function public.can_edit_shared_file(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.files f
    join public.file_shares s on s.file_id = f.id
    where f.id = p_file_id
      and s.shared_with = p_user_id
      and s.can_edit
      and (s.expires_at is null or s.expires_at > now())
  );
$$;

create or replace function public.is_file_owner(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.files f
    where f.id = p_file_id
      and f.owner_id = p_user_id
  );
$$;

create or replace function public.prevent_file_owner_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.owner_id is distinct from old.owner_id then
    raise exception 'file owner cannot be changed';
  end if;
  return new;
end;
$$;

create trigger files_prevent_owner_change
before update on public.files
for each row execute function public.prevent_file_owner_change();

create policy accounts_select_own
on public.accounts
for select
to authenticated
using (user_id = auth.uid());

create policy files_select_own_or_shared
on public.files
for select
to authenticated
using (
  owner_id = auth.uid()
  or public.can_access_file(id, auth.uid())
);

create policy files_insert_own
on public.files
for insert
to authenticated
with check (owner_id = auth.uid());

create policy files_update_own_or_shared_edit
on public.files
for update
to authenticated
using (
  owner_id = auth.uid()
  or public.can_edit_shared_file(id, auth.uid())
)
with check (
  owner_id = auth.uid()
  or public.can_edit_shared_file(id, auth.uid())
);

create policy files_delete_own
on public.files
for delete
to authenticated
using (owner_id = auth.uid());

create policy file_shares_select_own_file_or_shared_with
on public.file_shares
for select
to authenticated
using (
  public.is_file_owner(file_id, auth.uid())
  or shared_with = auth.uid()
);

create policy file_shares_insert_own_file
on public.file_shares
for insert
to authenticated
with check (public.is_file_owner(file_id, auth.uid()));

create policy file_shares_update_own_file
on public.file_shares
for update
to authenticated
using (public.is_file_owner(file_id, auth.uid()))
with check (public.is_file_owner(file_id, auth.uid()));

create policy file_shares_delete_own_file
on public.file_shares
for delete
to authenticated
using (public.is_file_owner(file_id, auth.uid()));

revoke all on public.accounts from anon;
revoke all on public.files from anon;
revoke all on public.file_shares from anon;

revoke all on public.accounts from authenticated;
revoke all on public.files from authenticated;
revoke all on public.file_shares from authenticated;

grant select on public.accounts to authenticated;
grant select, insert, update, delete on public.files to authenticated;
grant select, insert, update, delete on public.file_shares to authenticated;

grant all on public.accounts to service_role;
grant all on public.files to service_role;
grant all on public.file_shares to service_role;

revoke execute on function public.is_suspended(uuid) from public, anon;
revoke execute on function public.can_access_file(bigint, uuid) from public, anon;
revoke execute on function public.can_edit_shared_file(bigint, uuid) from public, anon;
revoke execute on function public.is_file_owner(bigint, uuid) from public, anon;
revoke execute on function public.prevent_file_owner_change() from public, anon;

grant execute on function public.is_suspended(uuid) to authenticated, service_role;
grant execute on function public.can_access_file(bigint, uuid) to authenticated, service_role;
grant execute on function public.can_edit_shared_file(bigint, uuid) to authenticated, service_role;
