alter table public.restaurants enable row level security;
alter table public.restaurant_staff enable row level security;
alter table public.reservations enable row level security;

create or replace function public.is_staff_at(p_restaurant_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.restaurant_staff
    where restaurant_id = p_restaurant_id
      and user_id = auth.uid()
  );
$$;

create or replace function public.enforce_reservation_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.restaurant_id is distinct from old.restaurant_id
     or new.user_id is distinct from old.user_id
     or new.reserved_for is distinct from old.reserved_for
     or new.party_size is distinct from old.party_size then
    raise exception 'Only the status of a reservation may be updated';
  end if;

  if old.status <> 'booked' then
    raise exception 'Only booked reservations can be updated';
  end if;

  if public.is_staff_at(old.restaurant_id) then
    if old.reserved_for > now() then
      raise exception 'Staff can only mark past reservations as seated or no_show';
    end if;
    if new.status not in ('seated', 'no_show') then
      raise exception 'Staff can only mark reservations as seated or no_show';
    end if;
    return new;
  end if;

  if old.reserved_for <= now() then
    raise exception 'Only future reservations can be cancelled';
  end if;

  if new.status <> 'cancelled' then
    raise exception 'Guests can only cancel their own reservations';
  end if;

  return new;
end;
$$;

create policy "restaurants_select_authenticated"
on public.restaurants
for select
to authenticated
using (true);

create policy "reservations_select_own_or_staff"
on public.reservations
for select
to authenticated
using (
  user_id = auth.uid()
  or public.is_staff_at(restaurant_id)
);

create policy "reservations_insert_own_future"
on public.reservations
for insert
to authenticated
with check (
  user_id = auth.uid()
  and reserved_for > now()
  and status = 'booked'
);

create policy "reservations_update_own_or_staff"
on public.reservations
for update
to authenticated
using (
  user_id = auth.uid()
  or public.is_staff_at(restaurant_id)
)
with check (
  user_id = auth.uid()
  or public.is_staff_at(restaurant_id)
);

create trigger enforce_reservation_update
before update on public.reservations
for each row
execute function public.enforce_reservation_update();

revoke all on public.restaurants from anon, authenticated;
revoke all on public.restaurant_staff from anon, authenticated;
revoke all on public.reservations from anon, authenticated;

