    or exists (
      select 1
      from public.pharmacists p
      where p.user_id = auth.uid()
    )
  );

create policy "dispenses_select_patient_or_pharmacist"
  on public.dispenses
  for select
  to authenticated
  using (
    exists (
      select 1
      from public.prescriptions p
      where p.id = dispenses.prescription_id
        and p.patient_id = auth.uid()
    )
    or exists (
      select 1
      from public.pharmacists p
      where p.user_id = auth.uid()
    )
  );

create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_pharmacist_id uuid := auth.uid();
  v_prescription public.prescriptions%rowtype;
  v_refills_left integer;
begin
  if v_pharmacist_id is null then
    raise exception 'Not authenticated';
  end if;

  select *
    into v_prescription
    from public.prescriptions
   where id = p_prescription_id
   for update;

  if not found then
    raise exception 'Prescription not found';
  end if;

  if v_prescription.expires_at < now() then
    raise exception 'Prescription has expired';
  end if;

  if v_prescription.patient_id = v_pharmacist_id then
    raise exception 'Cannot dispense your own prescription';
  end if;

  if not exists (
    select 1
      from public.pharmacists p
     where p.user_id = v_pharmacist_id
  ) then
    raise exception 'Caller is not a pharmacist';
  end if;

  if v_prescription.refills_left <= 0 then
    raise exception 'No refills left';
  end if;

  update public.prescriptions
     set refills_left = refills_left - 1
   where id = p_prescription_id;

  v_refills_left := v_prescription.refills_left - 1;

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, v_pharmacist_id);

  return v_refills_left;
end;
$$;

