alter table public.envelopes enable row level security;
alter table public.envelope_recipients enable row level security;

create policy envelopes_select on public.envelopes
  for select to authenticated
  using (sender_id = auth.uid() or exists (select 1 from public.envelope_recipients r where r.envelope_id = envelopes.id and r.user_id = auth.uid()));

create policy envelope_recipients_select on public.envelope_recipients
  for select to authenticated
  using (exists (select 1 from public.envelopes e where e.id = envelope_recipients.envelope_id and (e.sender_id = auth.uid() or envelope_recipients.user_id = auth.uid())));

create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_signed_at timestamptz;
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id for update;
  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if not exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid) then
    raise exception 'not a recipient';
  end if;

  if v_envelope.id = p_envelope_id and exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid and r.signed_at is not null) then
    raise exception 'already signed';
  end if;

  select r.sign_order into v_signed_at from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid;
  if v_signed_at is null then
    raise exception 'not a recipient';
  end if;

  if exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.sign_order < v_signed_at and r.signed_at is null) then
    raise exception 'a recipient earlier in sign order has not signed yet';
  end if;

  update public.envelope_recipients set signed_at = now() where envelope_id = p_envelope_id and user_id = v_uid;
  update public.envelopes set status = (
    select case when count(*) = (select count(*) from public.envelope_recipients r where r.envelope_id = p_envelope_id) then 'completed' else 'sent' end
    from public.envelope_recipients r where r.envelope_id = p_envelope_id
  ) where id = p_envelope_id;

  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id for update;
  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.sender_id <> v_uid then
    raise exception 'only the sender can void an envelope';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  update public.envelopes set status = 'voided' where id = p_envelope_id;

  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

revoke all on public.envelopes from anon;
revoke all on public.envelope_recipients from anon;
revoke all on public.envelopes from authenticated;
revoke all on public.envelope_recipients from authenticated;

