create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_envelope public.envelopes%rowtype;
  v_user uuid := auth.uid();
  v_status text;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if not exists (
    select 1
    from public.envelope_recipients
    where envelope_id = p_envelope_id
      and user_id = v_user
  ) then
    raise exception 'not a recipient';
  end if;

  if exists (
    select 1
    from public.envelope_recipients
    where envelope_id = p_envelope_id
      and user_id = v_user
      and signed_at is not null
  ) then
    raise exception 'already signed';
  end if;

  if exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.sign_order < (
        select r2.sign_order
        from public.envelope_recipients r2
        where r2.envelope_id = p_envelope_id
          and r2.user_id = v_user
      )
      and r.signed_at is null
  ) then
    raise exception 'a previous recipient has not signed yet';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = v_user;

  update public.envelopes
  set status = (
    select case
      when count(*) = 0 then 'voided'
      when count(*) > 0 and count(signed_at) = count(*) then 'completed'
      else 'sent'
    end
    from public.envelope_recipients
    where envelope_id = p_envelope_id
