create function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_signed_at timestamptz;
  v_order integer;
  v_count integer;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id for update;
  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if not exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_uid) then
    raise exception 'not a recipient';
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id and user_id = v_uid
     and signed_at is null
  returning sign_order into v_order;

  if not found then
    raise exception 'already signed';
  end if;

  select count(*) into v_count
    from public.envelope_recipients
   where envelope_id = p_envelope_id and signed_at is not null;

  select count(*) into v_count
    from public.envelope_recipients
   where envelope_id = p_envelope_id and sign_order < v_order and signed_at is null;

  if v_count > 0 then
    raise exception 'a previous signer has not signed yet';
  end if;

  update public.envelopes
     set status = 'completed'
   where id = p_envelope_id;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

