create function private.is_reviewer() returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.reviewers r where r.user_id = auth.uid())
$$;

create function private.proposal_decided(p_proposal_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce((select p.status = 'accepted' or p.status = 'rejected' from public.proposals p where p.id = p_proposal_id), false)
$$;

alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

create policy reviewers_select on public.reviewers
  for select to authenticated
  using (user_id = auth.uid());

create policy proposals_select on public.proposals
  for select to authenticated
  using (speaker_id = auth.uid() or private.is_reviewer());

create policy proposals_insert on public.proposals
  for insert to authenticated
  with check (speaker_id = auth.uid() and status = 'submitted');

create policy proposals_update on public.proposals
  for update to authenticated
  using (speaker_id = auth.uid() and status = 'submitted')
  with check (speaker_id = auth.uid() and status in ('submitted', 'accepted', 'rejected'));

create policy reviews_select on public.reviews
  for select to authenticated
  using (reviewer_id = auth.uid() or (private.is_reviewer() and private.proposal_decided(proposal_id)));

create policy reviews_insert on public.reviews
  for insert to authenticated
  with check (
    reviewer_id = auth.uid()
    and not private.is_reviewer()
    and private.proposal_decided(proposal_id) = false
  );

create policy reviews_update on public.reviews
  for update to authenticated
  using (reviewer_id = auth.uid() and private.proposal_decided(proposal_id) = false)
  with check (
    reviewer_id = auth.uid()
    and private.proposal_decided(proposal_id) = false
  );

create function public.reviews_guard() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if current_user = 'service_role' or auth.role() = 'service_role' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.reviewer_id is distinct from auth.uid() then
      raise exception 'reviewer_id must match the authenticated user' using errcode = '42501';
    end if;
    if not exists (select 1 from public.reviewers r where r.user_id = auth.uid()) then
      raise exception 'not a reviewer' using errcode = '42501';
    end if;
    if exists (select 1 from public.reviews where proposal_id = new.proposal_id and reviewer_id = new.reviewer_id) then
      raise exception 'review already exists' using errcode = '42501';
    end if;
    if not exists (select 1 from public.proposals p where p.id = new.proposal_id and p.status = 'submitted') then
      raise exception 'only submitted proposals can be reviewed' using errcode = '42501';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.reviewer_id is distinct from old.reviewer_id then
      raise exception 'reviewer_id cannot be changed' using errcode = '42501';
    end if;
    if not exists (select 1 from public.reviews where proposal_id = new.proposal_id and reviewer_id = new.reviewer_id) then
      raise exception 'review does not exist' using errcode = '42501';
    end if;
    if exists (select 1 from public.proposals p where p.id = new.proposal_id and p.status in ('accepted', 'rejected')) then
      raise exception 'proposal decision made' using errcode = '42501';
    end if;
  end if;
  return new;
end
$$;

create trigger reviews_guard
  before insert or update on public.reviews
  for each row execute function public.reviews_guard();

revoke all on public.reviewers from anon, authenticated;
revoke all on public.proposals from anon, authenticated;
revoke all on public.reviews from anon, authenticated;
revoke all on sequence public.proposals_id_seq from anon, authenticated;

grant select on public.reviewers to authenticated;
grant select, insert, update on public.proposals to authenticated;
grant select, insert, update on public.reviews to authenticated;
grant usage, select on sequence public.proposals_id_seq to authenticated;

